package com.elektoryk.scan.ui;

import android.Manifest;import android.app.Activity;import android.content.*;import android.content.pm.PackageManager;import android.os.Build;import android.os.Bundle;import android.widget.*;
import com.elektoryk.scan.audio.ConsultationRecordingService;import com.elektoryk.scan.model.*;import com.elektoryk.scan.storage.*;import java.util.*;

/** Main field dashboard for one object. Keeps the whole client-to-handover workflow on one screen. */
public class ObjectFlowActivity extends Activity{
 private static final int REQ_AUDIO=910,REQ_NOTIFICATIONS=911;private String projectId;private ObjectFlowRepository flowRepo;private ObjectFlowState flow;private TextView recStatus;
 @Override protected void onCreate(Bundle b){super.onCreate(b);projectId=getIntent().getStringExtra("projectId");flowRepo=new ObjectFlowRepository(this);render();}
 @Override protected void onResume(){super.onResume();if(projectId!=null){flow=flowRepo.load(projectId);render();maybeAutoRecord();}}
 private void render(){if(projectId==null)return;flow=flowRepo.load(projectId);ElectricalProject p=new FileProjectRepository(this).get(projectId);FloorPlan floor=new FloorPlanRepository(this).load(projectId);SceneSnapshot scene=new SceneRepository(this).loadScene(projectId);CommercialPlan commercial=new CommercialRepository(this).load(projectId);ClientApproval approval=new ApprovalRepository(this).load(projectId);
   ScrollView s=new ScrollView(this);s.setBackgroundColor(Ui.BG);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(Ui.dp(this,14),Ui.dp(this,14),Ui.dp(this,14),Ui.dp(this,30));s.addView(root);
   root.addView(Ui.brandHeader(this,"ELEKTORYK • Об'єкт",p==null?"Повний цикл робіт":p.displayName(),"FIELD FLOW",true));
   root.addView(Ui.screenIntro(this,"ОДИН ПРОЦЕС","Від першої розмови до здачі","Бриф → 2+ проходи скану → аналіз → Digital Twin → погодження → кошторис → закупівля → монтаж → правки → as-built → здача. Не треба шукати функції по всій програмі."),Ui.lpMatchWrap(this,10));
   Button tech=Ui.secondaryButton(this,"⚙ Технічні параметри об'єкта / метод монтажу");tech.setOnClickListener(v->open(ProjectActivity.class));root.addView(tech,Ui.lpMatchWrap(this,8));
   LinearLayout rec=Ui.card(this);rec.addView(Ui.title(this,"● Домовленості з клієнтом",18));recStatus=Ui.muted(this,recordingText());rec.addView(recStatus);Button rb=Ui.secondaryButton(this,isRecordingThisProject()?"■ Зупинити аудіозапис":"● Почати аудіозапис");rb.setOnClickListener(v->{if(isRecordingThisProject())stopRecording();else startRecording();});rec.addView(rb,Ui.lpMatchWrap(this,8));Button audioLog=Ui.secondaryButton(this,"Записи консультацій • "+flow.consultationAudioFiles.size());audioLog.setOnClickListener(v->open(ConsultationLogActivity.class));rec.addView(audioLog,Ui.lpMatchWrap(this,7));rec.addView(Ui.muted(this,"Запис доступний лише після зафіксованої згоди клієнта. Працює у foreground-режимі, тому не зникає, коли відкриваєш скан, план чи кошторис."),Ui.lpMatchWrap(this,5));root.addView(rec,Ui.lpMatchWrap(this,10));
   int points=floor==null?0:floor.points.size();int sockets=0,switches=0,lights=0,wallLights=0,panels=0; if(floor!=null)for(ElectricalPoint e:floor.points){if(e.type==ElectricalPoint.Type.SOCKET)sockets+=Math.max(1,e.moduleCount);if(e.type==ElectricalPoint.Type.SWITCH)switches+=Math.max(1,e.moduleCount);if(e.type==ElectricalPoint.Type.LIGHT){if("LIGHT_SCONCE".equals(e.assetKey))wallLights++;else lights++;}if(e.type==ElectricalPoint.Type.PANEL)panels++;}
   root.addView(stage("1","Бриф клієнта",flow.briefConfirmed?"Зафіксовано":"Потрібно уточнити",briefSummary(),"Відкрити бриф",ClientBriefActivity.class),Ui.lpMatchWrap(this,10));
   LinearLayout scan=stage("2","Скан квартири",flow.completedScanPasses>=flow.desiredScanPasses?"Проходи виконано":flow.completedScanPasses+" / "+flow.desiredScanPasses+" проходів",scene==null?"Ще немає проаналізованої сцени":"Сцена є • стін "+(scene.apartmentPlan==null?0:scene.apartmentPlan.walls.size())+" • рекомендовано дивитися gaps після кожного проходу","Smart Scan",ArCoreScanActivity.class);Button analysis=Ui.secondaryButton(this,flow.analysisConfirmed?"✓ Аналіз перевірено":"Підтвердити аналіз після перевірки");analysis.setOnClickListener(v->{flow.analysisConfirmed=!flow.analysisConfirmed;flowRepo.save(flow);render();});scan.addView(analysis,Ui.lpMatchWrap(this,7));root.addView(scan,Ui.lpMatchWrap(this,10));
   LinearLayout twin=stage("3","Digital Twin + точки",points>0?points+" точок":"Ще без точок",String.format(Locale.US,"Побажання / факти: розетки %d/%d • вимикачі %d/%d • світло %d/%d • бра %d/%d • щит %d/%d",flow.requestedSockets,sockets,flow.requestedSwitches,switches,flow.requestedLights,lights,flow.requestedWallLights,wallLights,flow.requestedPanels,panels),"Відкрити Digital Twin",DigitalTwinActivity.class);Button present=Ui.secondaryButton(this,"◈ Показати клієнту");present.setOnClickListener(v->open(ClientPresentationActivity.class));twin.addView(present,Ui.lpMatchWrap(this,7));Button compare=Ui.secondaryButton(this,"Розетки / світло / щит • порівняти варіанти");compare.setOnClickListener(v->open(ProductCompareActivity.class));twin.addView(compare,Ui.lpMatchWrap(this,7));root.addView(twin,Ui.lpMatchWrap(this,10));
   LinearLayout agree=stage("4","Узгодження",approval!=null&&approval.planApproved?"План погоджено":"Ще не погоджено","Підпис, версія проєкту та підтвердження кошторису зберігаються окремо від самого плану.","Підпис / погодження",ClientApprovalActivity.class);Button rev=Ui.secondaryButton(this,"V1 / V2 / правки клієнта");rev.setOnClickListener(v->open(RevisionActivity.class));agree.addView(rev,Ui.lpMatchWrap(this,7));Button ev=Ui.secondaryButton(this,"Додати скрін / фото / доказ");ev.setOnClickListener(v->open(EvidenceActivity.class));agree.addView(ev,Ui.lpMatchWrap(this,7));root.addView(agree,Ui.lpMatchWrap(this,10));
   LinearLayout est=stage("5","Кошторис і закупівля",commercial!=null&&commercial.total>0?String.format(Locale.US,"%.0f грн",commercial.total):"Потрібно порахувати","Технічні кількості → матеріали → упаковки → склад → ціна → націнка → хто закуповує → куплено/отримано.","Кошторис / закупівля",EstimateActivity.class);root.addView(est,Ui.lpMatchWrap(this,10));
   LinearLayout work=stage("6","Монтаж",points>0?"Готовий до деталізації":"Спочатку точки","CUT-відрізки, групи, захист, спільні коридори по стелі, траси і контроль монтажу.","Приступити / продовжити роботу",FieldWorkActivity.class);Button routes=Ui.secondaryButton(this,"⚡ Траси по стелі / стінах");routes.setOnClickListener(v->open(RoutingActivity.class));work.addView(routes,Ui.lpMatchWrap(this,7));Button crew=Ui.secondaryButton(this,"👷 Підсобник / години / витрати");crew.setOnClickListener(v->open(CrewActivity.class));work.addView(crew,Ui.lpMatchWrap(this,7));root.addView(work,Ui.lpMatchWrap(this,10));
   LinearLayout finish=stage("7","As-built і завершення",approval!=null&&approval.handoverAccepted?"Об'єкт прийнято":"Ще в роботі","Фото прихованих робіт, фактичний стан, ревізії, звіт і фінальне приймання.","Завершення / паспорт",HandoverActivity.class);Button evidence=Ui.secondaryButton(this,"Фото прихованих робіт");evidence.setOnClickListener(v->open(EvidenceActivity.class));finish.addView(evidence,Ui.lpMatchWrap(this,7));root.addView(finish,Ui.lpMatchWrap(this,10));
   root.addView(Ui.bottomNav(this,projectId,"HOME"),Ui.lpMatchWrap(this,18));setContentView(s);
 }
 private LinearLayout stage(String no,String title,String status,String desc,String action,Class<?> target){LinearLayout c=Ui.card(this);c.addView(Ui.chip(this,"ЕТАП "+no));c.addView(Ui.title(this,title,19),Ui.lpMatchWrap(this,5));TextView st=Ui.muted(this,status);st.setTextColor(Ui.GOLD);c.addView(st);c.addView(Ui.muted(this,desc),Ui.lpMatchWrap(this,5));Button b=Ui.button(this,action);b.setOnClickListener(v->open(target));c.addView(b,Ui.lpMatchWrap(this,9));return c;}
 private String briefSummary(){String budget=flow.budgetMax>0?String.format(Locale.US," • бюджет %.0f–%.0f грн",flow.budgetMin,flow.budgetMax):"";return "Розетки "+flow.requestedSockets+" • вимикачі "+flow.requestedSwitches+" • світло "+flow.requestedLights+" • бра "+flow.requestedWallLights+budget+" • "+flow.workClass.name();}
 private String activeRecordingProject(){android.content.SharedPreferences p=getSharedPreferences("consultation_recording",MODE_PRIVATE);return p.getLong("startedAt",0)>0?p.getString("projectId",""):"";}
 private boolean isRecordingThisProject(){return projectId!=null&&projectId.equals(activeRecordingProject());}
 private String recordingText(){android.content.SharedPreferences p=getSharedPreferences("consultation_recording",MODE_PRIVATE);String active=activeRecordingProject();if(projectId.equals(active))return "ЗАПИС ІДЕ • мікрофон активний • файлів збережено: "+flow.consultationAudioFiles.size();if(!active.isEmpty())return "Запис уже йде для іншого об'єкта. Спочатку зупини його там або зі сповіщення.";String ep=p.getString("errorProject","");String err=p.getString("lastError","");if(projectId.equals(ep)&&!err.isEmpty())return "Остання помилка запису: "+err;return flow.clientRecordingConsent?"Згода зафіксована • запис зараз вимкнений • файлів: "+flow.consultationAudioFiles.size():"Згода на запис ще не зафіксована в брифі.";}
 private void maybeAutoRecord(){if(flow!=null&&flow.clientRecordingConsent&&flow.autoRecordConsultation&&activeRecordingProject().isEmpty())startRecording();}
 private void startRecording(){startRecording(false);}
 private void startRecording(boolean skipNotificationPrompt){String active=activeRecordingProject();if(!active.isEmpty()&&!projectId.equals(active)){Toast.makeText(this,"Запис уже йде для іншого об'єкта. Спочатку зупини його.",Toast.LENGTH_LONG).show();if(recStatus!=null)recStatus.setText("Запис уже йде для іншого об'єкта.");return;}if(!flow.clientRecordingConsent){Toast.makeText(this,"Спочатку зафіксуй згоду клієнта в брифі.",Toast.LENGTH_LONG).show();open(ClientBriefActivity.class);return;}if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},REQ_AUDIO);return;}if(!skipNotificationPrompt&&Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED&&!getSharedPreferences("consultation_recording_settings",MODE_PRIVATE).getBoolean("notificationAsked",false)){getSharedPreferences("consultation_recording_settings",MODE_PRIVATE).edit().putBoolean("notificationAsked",true).apply();requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},REQ_NOTIFICATIONS);return;}Intent i=new Intent(this,ConsultationRecordingService.class);i.setAction(ConsultationRecordingService.ACTION_START);i.putExtra(ConsultationRecordingService.EXTRA_PROJECT,projectId);try{startForegroundService(i);if(recStatus!=null)recStatus.setText("Запускаю запис…"+(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED?" • системні сповіщення вимкнені":""));}catch(Exception e){new StabilityReporter(this).error("AUDIO_START","Foreground recorder could not start",e);String msg=e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();if(recStatus!=null)recStatus.setText("Не вдалося запустити запис: "+msg);Toast.makeText(this,"Запис не запущено: "+msg,Toast.LENGTH_LONG).show();}}
 private void stopRecording(){Intent i=new Intent(this,ConsultationRecordingService.class);i.setAction(ConsultationRecordingService.ACTION_STOP);startService(i);if(recStatus!=null)recStatus.setText("Запис зупинено.");}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==REQ_AUDIO&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)startRecording();else if(r==REQ_NOTIFICATIONS)startRecording(true);}
 private void open(Class<?> c){Intent i=new Intent(this,c);i.putExtra("projectId",projectId);startActivity(i);}
}
